/* Full-height app frame: the page does not scroll, the table container does. */
.page {
    box-sizing: border-box;
    height: 100vh;
    min-height: 480px;
    min-width: 0;
    padding: var(--g-spacing-6) var(--g-spacing-8);
}

.page__header {
    flex-shrink: 0;
}

.page__placeholder {
    flex: 1;
    min-height: 0;
    border: 1px dashed var(--g-color-line-generic);
    border-radius: var(--g-border-radius-l);
}

.orders {
    flex: 1;
    min-height: 0;
    min-width: 0;
}

.orders__toolbar {
    flex-shrink: 0;
}

.orders__selection {
    flex: 1;
    min-width: 0;
    justify-content: flex-end;
}

/* Horizontal and vertical scroll live inside the table widget only. */
.orders__table-scroll {
    flex: 1;
    min-height: 0;
    max-width: 100%;
    overflow: auto;
    border: 1px solid var(--g-color-line-generic);
    border-radius: var(--g-border-radius-l);
}

.orders__table {
    min-width: 100%;
}

@media (max-width: 768px) {
    .page {
        padding: var(--g-spacing-4);
    }

    .orders__selection {
        justify-content: flex-start;
    }
}

